INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (10, 320, "", 0, "", 20, 0, 2, 0, 23001, 20001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 321, "リリ", 125801, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, 0, 2, 1, 24001, 40011);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (2, 322, "クリア", 126001, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 1, 0, 2, 1, 24001, 40011);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (3, 323, "プレシア", 126101, "んーと。\nこれ、あげる。\nはい", 1, 0, 2, 1, 24001, 40011);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (4, 324, "リリ", 125801, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 1, 0, 2, 2, 24001, 40011);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (5, 325, "クリア", 126001, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 1, 0, 2, 2, 24001, 40011);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (6, 326, "プレシア", 126101, "お兄。\nきてくれて、うれしい", 1, 0, 2, 2, 24001, 40011);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 327, "", 0, "", 100, 532001, 8, 0, 91002, 80009);
